134	    /// [VS Code spec]: https://code.visualstudio.com/docs/languages/identifiers
135	    /// [VS Code extension]: https://github.com/withastro/language-tools/blob/0503392b80765c8a1292ddc9c063a1187425c187/packages/vscode/package.json#L140
136	    pub fn try_from_language_id(language_id: &str) -> Result<Self, FileSourceError> {
137	        match language_id {
