139	            "astro" => Ok(Self::astro()),
140	            "vuejs" | "vue" => Ok(Self::vue()),
141	            "svelte" => Ok(Self::svelte()),
142	            _ => Err(FileSourceError::UnknownLanguageId),
143	        }
144	    }
